import{z as n,x as A,o as t,c as B,q as E,j as o,D as e,d as l,s as r,S as s}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"YaRN","description":"","frontmatter":{"title":"YaRN","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/yarn.md","filePath":"llm/yarn.md","lastUpdated":1791413859000}'),p={name:"llm/yarn.md"};function h(d,a,m,_,N,R){const i=A("Mermaid");return t(),B("div",null,[a[2]||(a[2]=E('<h1 id="yarn" tabindex="-1">YaRN <a class="header-anchor" href="#yarn" aria-label="Permalink to &quot;YaRN&quot;">​</a></h1><div class="epigraph"><p>把神经正切核的频率缩放、位置插值与注意力温度放在同一套旋转变换里，RoPE 模型的上下文窗口可以高效延长。</p><footer>—— Peng 等，YaRN，2023</footer></div><p><a href="/llm/alibi">上一课</a>把位置写成注意力 logits 上与距离成正比的负偏置，斜率按头固定为几何序列。它从一开始按外推设计，但不能把现成 RoPE 模型无损换成 ALiBi。缺口是已经用 RoPE 训好的模型：窗口之外相位走出训练分布，注意力熵塌缩或发散。Chen 等人的位置插值把下标按比例压回原窗口，bloc97 的 NTK-aware 改基数以保住高频。Peng 等人 2023 年的 YaRN 按频率分段处理，再给 logits 乘与尺度有关的温度。本课写这套 RoPE 补丁，不重写 ALiBi 的斜率。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/alibi">ALiBi</a> 从零按外推设计偏置，帮不了已经用 RoPE 训好的权重。设原训练长度为 \\(L\\)，目标长度为 \\(L&#39;=sL\\)，\\(s\\gt 1\\) 为尺度。朴素外推仍用原来的 \\(\\theta_i\\) 去旋转位置 \\(L\\) 到 \\(L&#39;-1\\)。高频维度的角度增量本来就大，再乘更大的下标，旋转会在单位圆上走得太快，相邻 token 的相对相位变得像随机噪声。模型在训练里学到的「相对 \\(k\\) 步」对应某一段弧长，推理时这段弧长被拉长或卷绕，点积统计失真。</p><p>线性位置插值走相反方向：把位置换成 \\(p/s\\)，所有频率一起被压慢。低频的全局结构还在可插值的慢变区，高频的局部结构却被过度压缩——「差一个 token」与「差几个 token」在高频维度上变得难以分辨。NTK-aware 插值提高基数，让高频少受压缩，但又会让部分低频维度承担过多外推。单独用其中任何一种，都会在某一频段留下缺口。</p><p>YaRN 要解决的就是这个频段冲突：延长 RoPE 上下文窗口时，既不能让高频糊掉，也不能让低频相位溢出，还要处理尺度变大后注意力分布变尖或变平的问题。<span class="marginnote">RoPE 的每一维对应一个频率。插值与外推不能对所有维做同一件事：高频负责邻域，低频负责长程。YaRN 的核心判断是「按维分类处理」，而不是再选一个全局缩放系数。</span></p><p><span class="marginnote">数字实例：设原窗口 \\(L=8192\\)、尺度 \\(s=4\\)，目标窗口 32768。线性插值把位置下标除以 4，于是「相邻两个 token」在高频维上的角度差只剩原来的四分之一——好比把秒针换成四分慢速，「差一秒」和「差四秒」在表盘上几乎分不开了。这就是高频糊掉的直观来源。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>YaRN 把旋转维度分成三段。设第 \\(i\\) 维的波长为 \\(\\lambda_i=2\\pi/\\theta_i\\)。相对原窗口，若波长相对于新长度已经足够长，该维更接近外推；若波长很短、对应局部细节，该维更应该插值；中间一段用斜坡在两种策略之间过渡。论文称之为 NTK-by-parts：不是单一的 NTK 基数缩放，而是按维混合「插值」与「NTK 式外推」。</p><p>在此之上再加注意力温度。尺度 \\(s\\) 变大后，即使相位关系被校正，softmax 前的 logits 分布宽度也会变。YaRN 用与 \\(s\\) 有关的因子缩放注意力分数，经验形式为</p> \\[t = 0.1 \\ln s + 1 \\]<p><span class="marginnote">数字实例：温度公式算起来很快。\\(s=16\\) 时 \\(\\ln 16\\approx 2.77\\)，\\(t\\approx 1.28\\)；\\(s=64\\) 时 \\(\\ln 64\\approx 4.16\\)，\\(t\\approx 1.42\\)。窗口扩大 4 倍，温度只微调约 0.14——它是慢变函数，只需轻推 logits 的尺度，而不是重训。</span></p><p>再把 \\(q^\\top k/\\sqrt{d}\\) 除以或乘以与 \\(t\\) 相关的系数，使熵不随窗口拉长而系统性塌缩。温度不改变相对位置几何，只改变「有多尖」。</p>',14)),(t(),o(s,null,{default:e(()=>[r(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E5%8E%9F%20RoPE%20%E9%A2%91%E7%8E%87%22%5D%20--%3E%20H%5B%22%E9%AB%98%E9%A2%91%E7%BB%B4%E5%81%9A%E6%8F%92%E5%80%BC%22%5D%0A%20%20R%20--%3E%20M%5B%22%E4%B8%AD%E9%97%B4%E7%BB%B4%E6%96%9C%E5%9D%A1%E6%B7%B7%E5%90%88%22%5D%0A%20%20R%20--%3E%20L%5B%22%E4%BD%8E%E9%A2%91%E7%BB%B4%E5%81%9A%E5%A4%96%E6%8E%A8%22%5D%0A%20%20H%20--%3E%20Y%5B%22YaRN%20%E6%97%8B%E8%BD%AC%22%5D%0A%20%20M%20--%3E%20Y%0A%20%20L%20--%3E%20Y%0A%20%20Y%20--%3E%20T%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%E6%B8%A9%E5%BA%A6%E7%BC%A9%E6%94%BE%22%5D%0A%20%20T%20--%3E%20A%5B%22%E9%95%BF%E7%AA%97%E5%8F%A3%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p>可以只在推理时启用动态缩放，也可以在目标长度上做少量续训。Peng 等人强调：相对从头按长窗口预训练，续训步数可以少几个数量级，这是「高效延长」的工程含义。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="频率分组-插值与外推并存" tabindex="-1">频率分组：插值与外推并存 <a class="header-anchor" href="#频率分组-插值与外推并存" aria-label="Permalink to &quot;频率分组：插值与外推并存&quot;">​</a></h3><p>RoPE 点积里，第 \\(i\\) 对维度贡献一项正比于 \\(\\cos(\\theta_i\\Delta)\\) 的相对相位，其中 \\(\\Delta=p_q-p_k\\)。\\(\\theta_i\\) 大则 \\(\\Delta\\) 稍变，余弦就抖；\\(\\theta_i\\) 小则只有大 \\(\\Delta\\) 才看得出变化。线性插值令 \\(\\Delta\\leftarrow\\Delta/s\\)，所有 \\(\\theta_i\\Delta\\) 同时缩小，高频的 \\(\\theta_i\\Delta\\) 从「能分辨邻域」掉到「几乎常数」，局部位置分辨率损失。NTK-aware 提高基数、让高频 \\(\\theta\\) 几乎不动，本意是让高频在新窗口里仍有足够转角，但同一套公式也会改变低频，使部分长程维的相位超出训练弧长。</p><p>NTK-by-parts 按波长与 \\(L\\)、\\(s\\) 的关系决定该维用插值、外推还是斜坡。高频维吃插值，保住「差一个 token」的可分辨性；低频维吃外推，避免被无意义地压得更慢；中间维连续过渡，减少硬切带来的频谱裂缝。这不是三套独立的位置编码，而是同一旋转矩阵里不同对角块的不同 \\(\\theta\\) 重映射。</p><h3 id="注意力温度" tabindex="-1">注意力温度 <a class="header-anchor" href="#注意力温度" aria-label="Permalink to &quot;注意力温度&quot;">​</a></h3><p>即使相位校正了，窗口从 \\(L\\) 变到 \\(sL\\)，参与 softmax 的键数量增加，logits 的极值统计会变。常见现象是注意力过度集中在少数 token，或反过来摊得过平。温度把 logits 的有效尺度写成 \\(s\\) 的慢变函数，使训练时学到的「几条主要键 + 一长串小质量」这一形状，在更长窗口里仍大致成立。<span class="marginnote">温度解决的是熵，不是相位。只调温度而沿用错误的 \\(\\theta\\)，高频照样糊；只改 \\(\\theta\\) 而不调温度，相对几何对了，分配却可能全部塌到最近邻或注意力汇点上。YaRN 把两件事拆开。</span></p><h3 id="与纯-pi、纯-ntk-的关系" tabindex="-1">与纯 PI、纯 NTK 的关系 <a class="header-anchor" href="#与纯-pi、纯-ntk-的关系" aria-label="Permalink to &quot;与纯 PI、纯 NTK 的关系&quot;">​</a></h3><p>位置插值是 YaRN 高频端的特例：那些维的位置被按 \\(s\\) 压缩。NTK-aware 是低频端与部分中间维的近亲：通过改基数改变波长。YaRN 不发明第三种位置编码，而是规定何时用第一种、何时用第二种。因此它是 RoPE 的续训与推理补丁，不能移植到 ALiBi 或绝对嵌入上——那些方法没有可分段的旋转频谱。</p>',9)),(t(),o(s,null,{default:e(()=>[r(i,{id:"mermaid-66",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E5%BB%B6%E9%95%BF%E7%AA%97%E5%8F%A3%E6%97%B6%2C%20%E5%93%AA%E4%B8%80%E9%A2%91%E6%AE%B5%E4%BC%9A%E5%87%BA%E9%97%AE%E9%A2%98%3F%22%7D%0A%20%20Q%20--%3E%20PI%5B%22%E7%BA%AF%E7%BA%BF%E6%80%A7%E6%8F%92%E5%80%BC%22%5D%0A%20%20Q%20--%3E%20NTK%5B%22%E7%BA%AF%20NTK-aware%22%5D%0A%20%20PI%20--%3E%20P1%5B%22%E9%AB%98%E9%A2%91%E8%A2%AB%E5%8E%8B%E7%B3%8A%3A%20%E9%82%BB%E5%9F%9F%E5%88%86%E8%BE%A8%E7%8E%87%E4%B8%A2%E5%A4%B1%22%5D%0A%20%20NTK%20--%3E%20N1%5B%22%E4%BD%8E%E9%A2%91%E7%9B%B8%E4%BD%8D%E6%BA%A2%E5%87%BA%3A%20%E9%95%BF%E7%A8%8B%E5%BC%A7%E9%95%BF%E8%B6%85%E7%BA%B2%22%5D%0A%20%20P1%20--%3E%20Y%5B%22YaRN%3A%20%E9%AB%98%E9%A2%91%E7%94%A8%20PI%2C%20%E4%BD%8E%E9%A2%91%E7%94%A8%20NTK%2C%20%E4%B8%AD%E9%97%B4%E6%96%9C%E5%9D%A1%E8%BF%87%E6%B8%A1%22%5D%0A%20%20N1%20--%3E%20Y%0A%20%20Y%20--%3E%20T%5B%22%E5%86%8D%E5%8F%A0%E6%B8%A9%E5%BA%A6%E4%BF%AE%20softmax%20%E7%86%B5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>YaRN 依赖原模型的 RoPE 实现细节：旋转作用在哪些维度、基数 \\(\\theta\\) 的默认值、是否对部分维关闭旋转。<span class="marginnote">常见误区：初学者容易把 YaRN 当成一种新的位置编码、想拿它从头预训练。实际上它是给<strong>已训好的 RoPE 权重</strong>打的补丁——训练早已完成，推理或续训时才把频率重映射与温度装上去。它不换位置编码「品种」，只是重新解释同一套旋转的频率参数。</span>错误的维顺序或错误的 \\(s\\) 会让分段阈值对不上，表现为某一长度之后重复或长程遗忘。动态 YaRN 在推理时按当前序列长度改 \\(s\\)，但尺度一变，缓存里已按旧 \\(\\theta\\) 旋转的键会失配，通常需要按请求锁定尺度或重算缓存；若同一批次混有极短与极长样本，温度与 \\(\\theta\\) 需要按样本或按请求选择。</p><p>少量续训通常优于纯推理补丁，尤其是目标长度远大于 \\(L\\) 时。续训数据若全是短样本再靠 YaRN 硬拉，模型仍可能不会用新增的窗口。YaRN 提供的是可用的位置几何，不是自动出现的长程算法。</p><p><span class="marginnote">与从头长窗口预训练相比，YaRN 省的是算力与数据，不是评测。需要在目标长度上量困惑度、大海捞针与真实文档任务；只看「能跑 128k」没有意义。分段阈值与温度系数来自论文的经验选择，换模型族时值得扫一遍，而不是当成物理常数。</span></p><h3 id="不该与-alibi-混用的场景" tabindex="-1">不该与 ALiBi 混用的场景 <a class="header-anchor" href="#不该与-alibi-混用的场景" aria-label="Permalink to &quot;不该与 ALiBi 混用的场景&quot;">​</a></h3><p>已经用 ALiBi 训练的模型没有 RoPE 频率可分，YaRN 无的放矢。反过来，RoPE 模型想「训短测长」却不肯改旋转、只加线性偏置，会与已有相位双重计算位置，行为难以解释。二者择一作为主位置通道，再决定是架构级外推还是续训级延窗。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>YaRN 面向已用 RoPE 训练的模型，用分段频率重映射延长上下文窗口。</li><li>高频维倾向插值以保留局部分辨率，低频维倾向外推以避免过度压缩。</li><li>注意力温度校正窗口变长后的 softmax 熵，不代替相位校正。</li><li>可推理时动态启用，也可在目标长度上少量续训，后者通常更稳。</li><li>它是 RoPE 补丁，不能套到 ALiBi 或绝对位置嵌入上。</li><li>能跑更长不等于会用更长；下游仍需在目标长度上评测。</li><li>出处：Peng 等，<em>YaRN: Efficient Context Window Extension of Large Language Models</em>，2023；方法上衔接 Chen 等位置插值（2023）与 bloc97 的 NTK-aware 社区方案（2023）。</li></ul>',8))])}const D=n(p,[["render",h]]);export{c as __pageData,D as default};
